// Build the combinations worth having warm before the morning peak.
// Generating copy ahead of time turns a checkout latency problem into an
// overnight batch problem, so the nudge card never waits on a language model.
const categories = ['electronics', 'travel', 'jewellery', 'apparel', 'healthcare'];
const languages = ['hi', 'en', 'ta', 'bn'];
const bands = [
  { amount: 15000, months: 3, emi: 5000, noCost: true, product: 'postpaid', partner: 'Paytm Postpaid' },
  { amount: 50000, months: 3, emi: 16667, noCost: true, product: 'postpaid', partner: 'Paytm Postpaid' },
  { amount: 90000, months: 9, emi: 10633, noCost: false, product: 'card', partner: 'Paytm HDFC Bank Credit Card' },
];

const combos = [];
for (const merchantCategory of categories) {
  for (const language of languages) {
    for (const band of bands) {
      combos.push({
        json: { merchantCategory, language, merchantName: 'Kroma Electronics', ...band },
      });
    }
  }
}

return combos;

// Report what the run achieved. `source` tells us whether Sarvam actually
// answered or the templates covered for it, which is worth knowing before a demo.
const items = $input.all().map((item) => item.json);
const bySource = {};
for (const item of items) {
  const key = item.source ?? 'failed';
  bySource[key] = (bySource[key] ?? 0) + 1;
}

return [{ json: { warmed: items.length, bySource, finishedAt: new Date().toISOString() } }];
